"""Generate/check the public MCP contract without connecting to a station."""

import argparse
import asyncio
import json
from pathlib import Path

from alice_mcp.server import mcp


async def render() -> str:
    lines = ["# MCP tool contract", "",
             "Generated by `scripts/snapshot_tools.py`. Do not edit by hand.",
             "", "Stdio only. Tool annotations are hints, not authorization gates.", ""]
    for tool in await mcp.list_tools():
        lines += [f"## `{tool.name}`", "", tool.description or "", "", "```json",
                  json.dumps({"inputSchema": tool.inputSchema,
                              "annotations": tool.annotations.model_dump() if tool.annotations
                              else {}}, indent=2, ensure_ascii=False), "```", ""]
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = Path(__file__).resolve().parents[1] / "docs/TOOLS.md"
    content = asyncio.run(render())
    if args.check:
        if not path.is_file() or path.read_text(encoding="utf-8") != content:
            raise SystemExit("MCP contract snapshot is stale")
        print("MCP contract snapshot: PASS")
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")


if __name__ == "__main__":
    main()
